# Homebrew formula for the paxel/tap tap — generated by the release workflow,
# which fills in the tagged version and the sha256 of each release tarball and
# pushes the result to the homebrew-tap repository as Formula/dedup.rb.
# Binary formula: it installs the prebuilt `dedup`.
class Dedup < Formula
  desc "Forensic data-inheritance triage: dedupe, diff and browse file piles"
  homepage "https://github.com/paxel/dedup-rs"
  version "0.8.0"
  license "MIT"

  on_macos do
    if Hardware::CPU.arm?
      url "https://github.com/paxel/dedup-rs/releases/download/v0.8.0/dedup-0.8.0-macos-arm64.tar.gz"
      sha256 "fa139fcfedbcbd83b894059f41f14c64c5bd035c116aca1a5c2e21a2d85409f8"
    else
      url "https://github.com/paxel/dedup-rs/releases/download/v0.8.0/dedup-0.8.0-macos-x86_64.tar.gz"
      sha256 "a4c6f02e42343b725ee5a4e5056f9b01b02ecbe152ad9f1f6af8eaf474b75d04"
    end
  end

  on_linux do
    url "https://github.com/paxel/dedup-rs/releases/download/v0.8.0/dedup-0.8.0-linux-x86_64.tar.gz"
    sha256 "8f3e84a782c4ce19b3e8ad3489ea992c3ea09a978d988ae313baa88664d94f99"
  end

  def install
    bin.install "dedup"
  end

  def caveats
    <<~EOS
      Optional tools unlock extra features (the app works without them):
        ffmpeg       — video previews, filmstrips, soundtrack playback
        poppler      — PDF page rendering (Render tab)
        libreoffice  — office/legacy document page rendering
    EOS
  end

  test do
    system "#{bin}/dedup", "--help"
  end
end
